// Fuso e idioma configuráveis no .env (CHRONOS_TIMEZONE / CHRONOS_LOCALE)
const ZONE = $env.CHRONOS_TIMEZONE || 'America/Sao_Paulo';
const LOCALE = $env.CHRONOS_LOCALE || 'pt-BR';
const projects = {};
for (const p of ($('Buscar projetos').first().json.results || [])) projects[p.id] = p.inbox_project ? 'Entrada' : p.name;

const localDue = (due) => {
  if (!due || !due.date) return null;
  const raw = String(due.date);
  if (!raw.includes('T')) return raw;
  return DateTime.fromISO(raw, { zone: ZONE }).toFormat("yyyy-MM-dd'T'HH:mm:ss");
};

const rawList = (nodeName) => {
  try { return $(nodeName).first().json.results || []; } catch (e) { return []; }
};

// "Tarefas de hoje" (query today) e "Tarefas atrasadas" (query today | overdue, para pegar
// também tarefas de hoje com hora já vencida) se sobrepõem. Junta por id e reclassifica
// localmente comparando com o horário atual no fuso configurado (CHRONOS_TIMEZONE) — nunca confia na noção
// de "hoje"/"atrasado" do próprio filtro do Todoist, que não é confiável para o fuso do usuário.
const merged = new Map();
for (const t of [...rawList('Tarefas de hoje'), ...rawList('Tarefas atrasadas')]) {
  if (!t.checked && !t.is_deleted) merged.set(t.id, t);
}

const nowSP = $now.setZone(ZONE);
const todaySP = nowSP.toFormat('yyyy-MM-dd');

const toEntry = (t) => ({
  id: t.id,
  content: t.content,
  project: projects[t.project_id] || 'Entrada',
  priority: t.priority || 1,
  due: localDue(t.due),
});
const sortFn = (a, b) => (b.priority - a.priority) || String(a.due || '').localeCompare(String(b.due || ''));

const today = [];
const overdue = [];
for (const t of merged.values()) {
  const raw = t.due && t.due.date ? String(t.due.date) : null;
  if (!raw) continue;
  const hasTime = raw.includes('T');
  // DateTime.fromISO(raw, { zone: ZONE }): se raw tem 'Z'/offset, parseia o instante absoluto
  // e converte para ZONE; se raw é "flutuante" (sem timezone, como o Todoist devolve quando
  // due.timezone é null), interpreta o horário como já sendo em ZONE — os dois formatos reais
  // que a API do Todoist retorna.
  const dueSP = DateTime.fromISO(raw, { zone: ZONE });
  const dueDateSP = dueSP.toFormat('yyyy-MM-dd');

  if (dueDateSP > todaySP) continue; // futuro (não deveria vir das queries, ignora por segurança)
  const isOverdue = dueDateSP < todaySP || (hasTime && dueSP < nowSP);
  (isOverdue ? overdue : today).push(toEntry(t));
}
today.sort(sortFn);
overdue.sort(sortFn);

const todayIds = new Set(today.map(t => t.id));
const overdueIds = new Set(overdue.map(t => t.id));
const inbox = rawList('Tarefas da Entrada')
  .filter(t => !t.checked && !t.is_deleted)
  .map(toEntry)
  .sort(sortFn)
  .filter(t => !todayIds.has(t.id) && !overdueIds.has(t.id));

// Agenda do Google Calendar (hoje) — uma resposta por agenda, pareada com 'Selecionar agendas'
let events = [];
let calendar_error = null; // falha ao consultar eventos
let calendar_note = null;  // listagem falhou → só a agenda principal
try {
  const sel = $('Selecionar agendas').all();
  const res = $('Google: eventos de hoje').all();
  if (sel[0] && sel[0].json.list_error) calendar_note = sel[0].json.list_error;
  res.forEach((it, i) => {
    const r = it.json || {};
    const label = (sel[i] && sel[i].json.calendar_label) || r.summary || 'Agenda';
    if (r.error) { calendar_error = calendar_error || String(r.error.message || r.error).slice(0, 160); return; }
    for (const e of (r.items || [])) {
      if (!e || e.status === 'cancelled') continue;
      const allDay = !!(e.start && e.start.date);
      const s = allDay ? null : DateTime.fromISO(e.start.dateTime).setZone(ZONE);
      const en = allDay || !e.end ? null : DateTime.fromISO(e.end.dateTime).setZone(ZONE);
      events.push({
        title: e.summary || '(sem título)',
        calendar: label,
        all_day: allDay,
        start: s ? s.toFormat('HH:mm') : null,
        end: en ? en.toFormat('HH:mm') : null,
        sort: s ? s.toMillis() : 0,
        location: e.location || null,
        link: e.htmlLink || null,
      });
    }
  });
} catch (e) { calendar_error = calendar_error || 'nós do Google Calendar não executaram'; }
events.sort((a, b) => a.sort - b.sort);
const agendaTxt = events.length
  ? events.map(e => (e.all_day ? 'dia inteiro' : e.start + '–' + e.end) + ' ' + e.title).join('; ')
  : 'nenhum compromisso';

const now = nowSP.setLocale(LOCALE);
const inboxList = inbox.slice(0, 40).map(t => '- id=' + t.id + ' | ' + t.content + (t.due ? ' (prazo ' + t.due + ')' : '')).join('\n');

const system = [
  'Você é o Chronos, um assistente de produtividade. O usuário tem tarefas soltas na Entrada (Inbox) do Todoist.',
  'Escolha as 3 tarefas mais simples e executáveis para o usuário fazer HOJE, priorizando: (1) as que têm prazo próximo ou vencido, (2) as que podem ser resolvidas em poucos minutos, (3) as que destravam outras coisas.',
  'Responda SOMENTE com JSON válido neste formato: {"suggestions": [{"id": "id exato da tarefa", "title": "título curto", "reason": "motivo em até 10 palavras"}]}',
  'Use exatamente os ids fornecidos. Se houver menos de 3 tarefas, sugira todas. Nunca invente tarefas.',
  '',
  'Hoje é ' + now.toFormat('cccc, dd/MM/yyyy') + '. O usuário já tem ' + today.length + ' tarefa(s) para hoje e ' + overdue.length + ' atrasada(s).',
  'Agenda de hoje no Google Calendar: ' + agendaTxt + '. Se o dia estiver cheio de compromissos, prefira tarefas curtas.',
  '',
  'EXEMPLO DE SAÍDA JSON: {"suggestions":[{"id":"abc123","title":"Ligar para o dentista","reason":"rápida e destrava a consulta"}]}',
].join('\n');

return [{ json: {
  today, overdue, inbox, events, calendar_error, calendar_note,
  has_inbox: inbox.length > 0,
  system,
  user: 'Tarefas na Entrada:\n' + inboxList,
  date_label: now.toFormat('cccc, dd/MM'),
} }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ctx = $('Preparar contexto').first().json;
const prio = (p) => ({ 4: '🔴 ', 3: '🟠 ', 2: '🔵 ' })[p] || '';
const ddmm = (iso) => iso ? iso.slice(8, 10) + '/' + iso.slice(5, 7) : '';
const hhmm = (iso) => iso && iso.includes('T') ? ' às ' + iso.slice(11, 16) : '';

let suggestions = [];
try {
  const raw = $('DeepSeek: sugerir 3 tarefas').first().json.choices[0].message.content;
  const parsed = JSON.parse(raw);
  const byId = {};
  for (const t of ctx.inbox) byId[t.id] = t;
  suggestions = (parsed.suggestions || [])
    .filter(s => s && byId[s.id])
    .slice(0, 3)
    .map(s => ({ id: s.id, title: byId[s.id].content, reason: s.reason || '' }));
} catch (e) { suggestions = []; }
if (suggestions.length === 0 && ctx.inbox.length > 0) {
  suggestions = ctx.inbox.slice(0, 3).map(t => ({ id: t.id, title: t.content, reason: 'primeiras da Entrada' }));
}

const MAX = 6;
const today = ctx.today.slice(0, MAX);
const overdue = ctx.overdue.slice(0, MAX);
let n = 0;
const lines = ['☀️ <b>Bom dia! Resumo de ' + esc(ctx.date_label) + '</b>', ''];
const keyboard = [];

const events = ctx.events || [];
const MAX_EV = 8;
lines.push('📅 <b>Agenda de hoje</b>' + (events.length ? ' (' + events.length + ')' : ''));
if (events.length === 0 && ctx.calendar_error) lines.push('<i>Google Calendar indisponível: ' + esc(ctx.calendar_error) + '</i>');
else if (events.length === 0) lines.push('<i>Nenhum compromisso hoje</i>');
if (ctx.calendar_note) lines.push('<i>(só a agenda principal — ' + esc(ctx.calendar_note) + ')</i>');
for (const e of events.slice(0, MAX_EV)) {
  lines.push('• ' + (e.all_day ? 'Dia inteiro' : e.start + '–' + e.end) + ' ' + esc(e.title) + ' <i>#' + esc(e.calendar) + '</i>' + (e.location ? ' 📍 ' + esc(e.location) : ''));
}
if (events.length > MAX_EV) lines.push('<i>… e mais ' + (events.length - MAX_EV) + '</i>');
lines.push('');

lines.push('📌 <b>Tarefas de hoje</b> (' + ctx.today.length + ')');
if (ctx.today.length === 0) lines.push('<i>Nenhuma tarefa para hoje 🎉</i>');
for (const t of today) {
  n++;
  lines.push(n + '. ' + prio(t.priority) + esc(t.content) + hhmm(t.due) + ' <i>#' + esc(t.project) + '</i>');
  keyboard.push([
    { text: n + ' ✅ Concluir', callback_data: 'done:' + t.id },
    { text: n + ' ⏰ Amanhã', callback_data: 'snooze:' + t.id },
  ]);
}
if (ctx.today.length > MAX) lines.push('<i>… e mais ' + (ctx.today.length - MAX) + '</i>');
lines.push('');

lines.push('⚠️ <b>Atrasadas</b> (' + ctx.overdue.length + ')');
if (ctx.overdue.length === 0) lines.push('<i>Nada atrasado 👏</i>');
for (const t of overdue) {
  n++;
  lines.push(n + '. ' + prio(t.priority) + esc(t.content) + ' <i>#' + esc(t.project) + ' · desde ' + ddmm(t.due) + hhmm(t.due) + '</i>');
  keyboard.push([
    { text: n + ' ✅ Concluir', callback_data: 'done:' + t.id },
    { text: n + ' ⏰ Hoje', callback_data: 'today:' + t.id },
  ]);
}
if (ctx.overdue.length > MAX) lines.push('<i>… e mais ' + (ctx.overdue.length - MAX) + '</i>');
lines.push('');

lines.push('💡 <b>Sugestões da Entrada</b> (' + ctx.inbox.length + ' pendentes)');
if (suggestions.length === 0) lines.push('<i>Entrada vazia — nada a sugerir.</i>');
for (const s of suggestions) {
  n++;
  lines.push(n + '. ' + esc(s.title) + (s.reason ? ' — <i>' + esc(s.reason) + '</i>' : ''));
  keyboard.push([
    { text: n + ' 📅 Fazer hoje', callback_data: 'today:' + s.id },
    { text: n + ' ✅ Já fiz', callback_data: 'done:' + s.id },
  ]);
}
lines.push('');
lines.push('<i>Botões: ⏰ Hoje/Amanhã reagenda mantendo o horário ou no próximo livre. Mande /hoje para repetir este resumo.</i>');

return [{ json: {
  chat_id: $env.TELEGRAM_CHAT_ID,
  text: lines.join('\n'),
  reply_markup: { inline_keyboard: keyboard },
} }];

// Opcional: CHRONOS_CALENDARS="Agenda A;Agenda B" restringe as agendas consultadas; vazio = todas as que você pode editar.
const WANTED = String($env.CHRONOS_CALENDARS || '').split(';').map((s) => s.trim()).filter(Boolean);
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s*(&|\be\b|\band\b)\s*/g, ' ').replace(/[^a-z0-9]/g, '');
const res = $json;
const fallback = (why) => [{ json: { calendar_id: 'primary', calendar_label: 'Agenda principal', list_error: why } }];

// Sem a lista (ex.: escopo OAuth só de eventos → 403), consulta ao menos a agenda principal.
if (res.error || !Array.isArray(res.items)) {
  return fallback(res.error ? String(res.error.message || res.error).slice(0, 160) : 'resposta inesperada do calendarList');
}
const wanted = new Set(WANTED.map(norm));
const out = res.items
  .filter(c => !c.deleted && !c.hidden && (!wanted.size || wanted.has(norm(c.summaryOverride || c.summary)) || wanted.has(norm(c.summary))))
  .map(c => ({ json: { calendar_id: c.id, calendar_label: c.summaryOverride || c.summary, list_error: null } }));
return out.length ? out : fallback(wanted.size ? 'nenhuma das agendas de CHRONOS_CALENDARS encontrada no Google Calendar' : 'nenhuma agenda encontrada no Google Calendar');
